const normalizeChannelName = (value) => {
  if (typeof value !== 'string') {
    return '';
  }

  const trimmed = value.trim();
  if (!trimmed) {
    return '';
  }

  return trimmed.replace(/^[#~]/, '');
};

const message = typeof $json.message === 'string' ? $json.message : '';
const channelId = typeof $json.channelId === 'string' ? $json.channelId.trim() : '';
const channelName = normalizeChannelName($json.channelName);
const teamName = typeof $json.teamName === 'string' ? $json.teamName.trim() : '';
const rootId = typeof $json.rootId === 'string' ? $json.rootId.trim() : '';

return [{
  json: {
    message,
    channelId,
    channelName,
    teamName,
    rootId
  }
}];

const normalized = $('Normalize input').item.json || {};
const config = $('Set Mattermost config').item.json || {};

const message = typeof normalized.message === 'string' ? normalized.message.trim() : '';
const inputChannelId = typeof normalized.channelId === 'string' ? normalized.channelId.trim() : '';
const inputChannelName = typeof normalized.channelName === 'string' ? normalized.channelName.trim() : '';
const inputTeamName = typeof normalized.teamName === 'string' ? normalized.teamName.trim() : '';
const rootId = typeof normalized.rootId === 'string' ? normalized.rootId.trim() : '';

const baseUrl = typeof config.baseUrl === 'string' ? config.baseUrl.trim().replace(/\/+$/, '') : '';
const defaultChannelId = typeof config.defaultChannelId === 'string' ? config.defaultChannelId.trim() : '';
const defaultChannelName = typeof config.defaultChannelName === 'string' ? config.defaultChannelName.trim().replace(/^[#~]/, '') : '';
const defaultTeamName = typeof config.defaultTeamName === 'string' ? config.defaultTeamName.trim() : '';

const usedChannelId = inputChannelId || defaultChannelId;
const usedChannelName = usedChannelId ? '' : (inputChannelName || defaultChannelName);
const usedTeamName = inputTeamName || defaultTeamName;
const needsChannelLookup = !usedChannelId;

let error = '';
if (!message) {
  error = 'Input field message is required and must be a non-empty string.';
} else if (!baseUrl) {
  error = 'No Mattermost baseUrl configured. Set value in node Set Mattermost config.';
} else if (!usedChannelId && !usedChannelName) {
  error = 'Provide channelId or channelName (or configure a default in node Set Mattermost config).';
} else if (!usedChannelId && !usedTeamName) {
  error = 'teamName is required when sending by channelName. Pass teamName or set defaultTeamName in node Set Mattermost config.';
}

return [{
  json: {
    message,
    rootId,
    baseUrl,
    usedChannelId,
    usedChannelName,
    usedTeamName,
    needsChannelLookup,
    okToSend: !error,
    error
  }
}];

const resolved = $('Resolve and validate payload').item.json || {};
const response = $json || {};
const statusCode = Number(response.statusCode || response.code || 0) || null;
const teamId = typeof response.id === 'string' ? response.id : '';
const errorMessage = response.error || response.message || response.detailed_error || '';
const ok = !!teamId && !errorMessage && (statusCode === null || statusCode < 400);

return [{
  json: {
    ...resolved,
    usedTeamId: teamId,
    teamLookupStatusCode: statusCode,
    teamLookupOk: ok,
    teamLookupResponse: response
  }
}];

const resolved = $('Evaluate team lookup').item.json || {};
const response = $json || {};
const statusCode = Number(response.statusCode || response.code || 0) || null;
const channelId = typeof response.id === 'string' ? response.id : '';
const channelName = typeof response.name === 'string' ? response.name : resolved.usedChannelName || '';
const errorMessage = response.error || response.message || response.detailed_error || '';
const ok = !!channelId && !errorMessage && (statusCode === null || statusCode < 400);

return [{
  json: {
    ...resolved,
    usedChannelId: channelId,
    usedChannelName: channelName,
    channelLookupStatusCode: statusCode,
    channelLookupOk: ok,
    channelLookupResponse: response
  }
}];

const resolved = $('Prepare send payload').item.json || {};
const response = $json || {};
const statusCode = Number(response.statusCode || response.code || 0) || null;
const errorMessage = response.error || response.message || response.detailed_error || '';
const ok = !!response.id && !errorMessage && (statusCode === null || (statusCode >= 200 && statusCode < 300));

return [{
  json: {
    ok,
    statusCode,
    usedChannelId: resolved.usedChannelId || null,
    usedChannelName: resolved.usedChannelName || null,
    usedTeamName: resolved.usedTeamName || null,
    response
  }
}];

return [{
  json: {
    ok: false,
    statusCode: null,
    usedChannelId: $json.usedChannelId || null,
    usedChannelName: $json.usedChannelName || null,
    usedTeamName: $json.usedTeamName || null,
    response: {
      error: $json.error || 'Invalid input'
    }
  }
}];

return [{
  json: {
    ok: false,
    statusCode: $json.teamLookupStatusCode || null,
    usedChannelId: null,
    usedChannelName: $json.usedChannelName || null,
    usedTeamName: $json.usedTeamName || null,
    response: {
      error: $json.teamLookupResponse?.error || $json.teamLookupResponse?.message || `Could not resolve team by name: ${$json.usedTeamName || 'unknown team'}`
    }
  }
}];

return [{
  json: {
    ok: false,
    statusCode: $json.channelLookupStatusCode || null,
    usedChannelId: null,
    usedChannelName: $json.usedChannelName || null,
    usedTeamName: $json.usedTeamName || null,
    response: {
      error: $json.channelLookupResponse?.error || $json.channelLookupResponse?.message || `Could not resolve channel by name: ${$json.usedChannelName || 'unknown channel'}`
    }
  }
}];
